use kino_core::render::Frames;
#[test]fn float_cache_quantizes_only_on_request(){let f=Frames{quantized:Default::default(),linear_buf:Some(vec![0.2,0.4,0.6,1.]),buf:vec![],fs:4,first:0};assert_eq!(f.len(),1);assert!(f.quantized.get().is_none());assert_eq!(f.get_float(0).unwrap()[0],0.2);assert!(f.quantized.get().is_none());assert_eq!(f.get(0).unwrap(),&[51,102,153,255]);assert!(f.quantized.get().is_some());}
